// End-to-end CV pipeline on synthetic perspective photos: corner warp -> cell features -> diff -> new tiles.
// Fixtures are generated by `python3 test/make_boards.py test/fixtures` (skipped if absent).
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {warp, cellFeatures, diffScores, pickNewCells, homography, applyH, packFeatures, unpackFeatures} from '../js/geom.js';

const dir = new URL('./fixtures/', import.meta.url);
const have = fs.existsSync(new URL('meta.json', dir));

test('homography maps corners exactly', () => {
  const sq = [{x: 0, y: 0}, {x: 1, y: 0}, {x: 1, y: 1}, {x: 0, y: 1}], q = [{x: 10, y: 5}, {x: 90, y: 12}, {x: 100, y: 80}, {x: 3, y: 70}];
  const H = homography(sq, q);
  sq.forEach((p, i) => { const m = applyH(H, p.x, p.y); assert.ok(Math.abs(m.x - q[i].x) < 1e-6 && Math.abs(m.y - q[i].y) < 1e-6); });
});

test('diff finds exactly the new tiles each turn', {skip: !have && 'no fixtures'}, () => {
  const meta = JSON.parse(fs.readFileSync(new URL('meta.json', dir)));
  const corners = meta.corners.map(([x, y]) => ({x, y})); // nominal corners; frames have +-3px jitter
  let prev = null, prevTiles = new Set();
  for (const f of meta.frames) {
    const data = new Uint8ClampedArray(fs.readFileSync(new URL(f.file + '.rgba', dir)));
    const feats = unpackFeatures(packFeatures(cellFeatures(warp({width: f.w, height: f.h, data}, corners, 600))));
    const tiles = new Set(f.tiles.map(([r, c]) => r * 15 + c));
    if (prev) {
      const occupied = Array.from({length: 225}, (_, i) => prevTiles.has(i));
      const {cells} = pickNewCells(diffScores(prev, feats), occupied);
      const got = cells.map(x => x.r * 15 + x.c).sort((a, b) => a - b);
      const want = [...tiles].filter(i => !prevTiles.has(i)).sort((a, b) => a - b);
      assert.deepEqual(got, want, f.file);
    }
    prev = feats; prevTiles = tiles;
  }
});
